INSERT INTO `translations` (`id`, `translationable_type`, `translationable_id`, `locale`, `key`, `value`) VALUES
(105, 'Modules\\ServiceManagement\\Entities\\Service', 'f5c493cc-cd84-4da0-b7d8-45bbbbb744bc', 'en', 'description', '<p data-start=\"86\" data-end=\"133\">🎉 <strong data-start=\"89\" data-end=\"131\">Gate Decoration &ndash; Starting from ₹9,999</strong></p>\r\n<p data-start=\"135\" data-end=\"406\">शादी का पहला impression होता है <em data-start=\"167\" data-end=\"184\">Gate Decoration</em>। जब मेहमान आपके शादी स्थल पर आते हैं, तो सबसे पहले उनकी नजर गेट की सजावट पर ही पड़ती है। Vivah Bazaar का Gate Decoration Package आपके shaadi के gate ko बनाता है <em data-start=\"346\" data-end=\"374\">grand, royal aur welcoming</em>, जिससे हर guest impressed हो।</p>\r\n<p data-start=\"408\" data-end=\"441\">✨ <strong data-start=\"410\" data-end=\"439\">इस पैकेज में आपको मिलेगा:</strong></p>\r\n<ul data-start=\"442\" data-end=\"716\">\r\n<li data-start=\"442\" data-end=\"482\">\r\n<p data-start=\"444\" data-end=\"482\">Gate Decoration सिर्फ ₹9,999 से शुरू</p>\r\n</li>\r\n<li data-start=\"483\" data-end=\"545\">\r\n<p data-start=\"485\" data-end=\"545\">Fresh flowers, decorative lights aur designer fabric setup</p>\r\n</li>\r\n<li data-start=\"546\" data-end=\"609\">\r\n<p data-start=\"548\" data-end=\"609\">Multiple themes &ndash; Traditional, Modern, Royal aur Customized</p>\r\n</li>\r\n<li data-start=\"610\" data-end=\"659\">\r\n<p data-start=\"612\" data-end=\"659\">Wide entry arches aur designer welcome boards</p>\r\n</li>\r\n<li data-start=\"660\" data-end=\"716\">\r\n<p data-start=\"662\" data-end=\"716\">Professional decorators aur time par setup की सुविधा</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"718\" data-end=\"777\">📌 <strong data-start=\"721\" data-end=\"775\">क्यों चुनें Vivah Bazaar Gate Decoration Services?</strong></p>\r\n<ul data-start=\"778\" data-end=\"969\">\r\n<li data-start=\"778\" data-end=\"816\">\r\n<p data-start=\"780\" data-end=\"816\">Affordable pricing सिर्फ ₹9,999 से</p>\r\n</li>\r\n<li data-start=\"817\" data-end=\"864\">\r\n<p data-start=\"819\" data-end=\"864\">Grand aur stylish सजावट जो सबको attract करे</p>\r\n</li>\r\n<li data-start=\"865\" data-end=\"914\">\r\n<p data-start=\"867\" data-end=\"914\">Fresh flowers aur premium decoration material</p>\r\n</li>\r\n<li data-start=\"915\" data-end=\"969\">\r\n<p data-start=\"917\" data-end=\"969\">Customized designs aur timely service की guarantee</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"971\" data-end=\"1093\">💍 शादी का gate ही आपके celebration का पहला look होता है, और हमारी सजावट आपके event ko aur भी royal aur यादगार बना देगी।</p>\r\n<p data-start=\"1095\" data-end=\"1180\">👉 अभी बुक करें और अपनी shaadi ke entry gate को दें grand aur royal सजावट का touch!</p>'),
(106, 'Modules\\ServiceManagement\\Entities\\Service', 'cfaff2e8-cf73-4b63-8c07-dd4a72335515', 'en', 'name', 'Bed Decoration'),
(107, 'Modules\\ServiceManagement\\Entities\\Service', 'cfaff2e8-cf73-4b63-8c07-dd4a72335515', 'en', 'short_description', 'Book Bed Decoration service from Vivah Bazaar, Prices starts from ₹5499'),
(108, 'Modules\\ServiceManagement\\Entities\\Service', 'cfaff2e8-cf73-4b63-8c07-dd4a72335515', 'en', 'description', '<p data-start=\"112\" data-end=\"158\">🌹 <strong data-start=\"115\" data-end=\"156\">Bed Decoration &ndash; Starting from ₹5,499</strong></p>\r\n<p data-start=\"160\" data-end=\"430\">शादी की पहली रात हर दूल्हा&ndash;दुल्हन के लिए <em data-start=\"201\" data-end=\"224\">सबसे खास और यादगार पल</em> होता है। इस रात की खूबसूरती बढ़ाने के लिए <em data-start=\"267\" data-end=\"283\">Bed Decoration</em> बेहद ज़रूरी है। Vivah Bazaar का Bed Decoration Package आपके कमरे को बनाता है <em data-start=\"361\" data-end=\"390\">romantic, elegant aur royal</em>, ताकि आपकी सुहागरात बन सके और भी खास।</p>\r\n<p data-start=\"432\" data-end=\"465\">✨ <strong data-start=\"434\" data-end=\"463\">इस पैकेज में आपको मिलेगा:</strong></p>\r\n<ul data-start=\"466\" data-end=\"740\">\r\n<li data-start=\"466\" data-end=\"505\">\r\n<p data-start=\"468\" data-end=\"505\">Bed Decoration सिर्फ ₹5,499 से शुरू</p>\r\n</li>\r\n<li data-start=\"506\" data-end=\"571\">\r\n<p data-start=\"508\" data-end=\"571\">Fresh flowers (गुलाब, रजनीगंधा, गेंदा आदि) aur designer setup</p>\r\n</li>\r\n<li data-start=\"572\" data-end=\"622\">\r\n<p data-start=\"574\" data-end=\"622\">Decorative candles, lights aur fragrance touch</p>\r\n</li>\r\n<li data-start=\"623\" data-end=\"685\">\r\n<p data-start=\"625\" data-end=\"685\">Multiple themes &ndash; Simple, Traditional, Romantic aur Luxury</p>\r\n</li>\r\n<li data-start=\"686\" data-end=\"740\">\r\n<p data-start=\"688\" data-end=\"740\">Professional decorators aur timely setup की सुविधा</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"742\" data-end=\"800\">📌 <strong data-start=\"745\" data-end=\"798\">क्यों चुनें Vivah Bazaar Bed Decoration Services?</strong></p>\r\n<ul data-start=\"801\" data-end=\"1004\">\r\n<li data-start=\"801\" data-end=\"839\">\r\n<p data-start=\"803\" data-end=\"839\">Affordable pricing सिर्फ ₹5,499 से</p>\r\n</li>\r\n<li data-start=\"840\" data-end=\"893\">\r\n<p data-start=\"842\" data-end=\"893\">Fresh flowers aur premium d&eacute;cor items का इस्तेमाल</p>\r\n</li>\r\n<li data-start=\"894\" data-end=\"948\">\r\n<p data-start=\"896\" data-end=\"948\">Customized designs (Traditional से लेकर Modern तक)</p>\r\n</li>\r\n<li data-start=\"949\" data-end=\"1004\">\r\n<p data-start=\"951\" data-end=\"1004\">Timely service aur client satisfaction की guarantee</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1006\" data-end=\"1144\">💍 शादी की पहली रात सिर्फ एक रात नहीं, बल्कि <em data-start=\"1051\" data-end=\"1072\">नई जिंदगी की शुरुआत</em> होती है। हमारी सजावट इस रात को और भी romantic aur यादगार बना देती है।</p>\r\n<p data-start=\"1146\" data-end=\"1225\">👉 अभी बुक करें और अपनी <em data-start=\"1170\" data-end=\"1187\">सुहागरात की रात</em> को दें एक royal aur romantic touch!</p>'),
(109, 'Modules\\ServiceManagement\\Entities\\Service', '423abe48-d00f-465a-a6ec-6f0b49fb8f69', 'en', 'name', 'Stage Decoration'),
(110, 'Modules\\ServiceManagement\\Entities\\Service', '423abe48-d00f-465a-a6ec-6f0b49fb8f69', 'en', 'short_description', 'Book Stage Decoration service from Vivah Bazaar, Prices starts from ₹9999'),
(111, 'Modules\\ServiceManagement\\Entities\\Service', '423abe48-d00f-465a-a6ec-6f0b49fb8f69', 'en', 'description', '<p data-start=\"63\" data-end=\"111\">🌟 <strong data-start=\"66\" data-end=\"109\">Stage Decoration &ndash; Starting from ₹9,999</strong></p>\r\n<p data-start=\"113\" data-end=\"444\">शादी में सबसे ज्यादा नज़रें जिस जगह पर टिकी रहती हैं, वो है <em data-start=\"173\" data-end=\"188\">wedding stage</em>। यहां दूल्हा&ndash;दुल्हन बैठते हैं और यहीं पर सबसे ज्यादा फोटोशूट भी होता है। अगर stage सजावट grand और royal हो तो पूरी shaadi का level ही अलग दिखता है। Vivah Bazaar का Stage Decoration Package आपके wedding stage को देता है <em data-start=\"408\" data-end=\"441\">premium, आकर्षक aur यादगार look</em>।</p>\r\n<p data-start=\"446\" data-end=\"479\">✨ <strong data-start=\"448\" data-end=\"477\">इस पैकेज में आपको मिलेगा:</strong></p>\r\n<ul data-start=\"480\" data-end=\"755\">\r\n<li data-start=\"480\" data-end=\"521\">\r\n<p data-start=\"482\" data-end=\"521\">Stage Decoration सिर्फ ₹9,999 से शुरू</p>\r\n</li>\r\n<li data-start=\"522\" data-end=\"577\">\r\n<p data-start=\"524\" data-end=\"577\">Fresh flowers, designer backdrop aur lighting setup</p>\r\n</li>\r\n<li data-start=\"578\" data-end=\"640\">\r\n<p data-start=\"580\" data-end=\"640\">Multiple themes &ndash; Traditional, Modern, Bollywood aur Royal</p>\r\n</li>\r\n<li data-start=\"641\" data-end=\"700\">\r\n<p data-start=\"643\" data-end=\"700\">Sofa / chair arrangement with premium draping aur सजावट</p>\r\n</li>\r\n<li data-start=\"701\" data-end=\"755\">\r\n<p data-start=\"703\" data-end=\"755\">Professional decorators aur timely setup की सुविधा</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"757\" data-end=\"817\">📌 <strong data-start=\"760\" data-end=\"815\">क्यों चुनें Vivah Bazaar Stage Decoration Services?</strong></p>\r\n<ul data-start=\"818\" data-end=\"1020\">\r\n<li data-start=\"818\" data-end=\"856\">\r\n<p data-start=\"820\" data-end=\"856\">Affordable pricing सिर्फ ₹9,999 से</p>\r\n</li>\r\n<li data-start=\"857\" data-end=\"909\">\r\n<p data-start=\"859\" data-end=\"909\">Fresh flowers aur premium quality d&eacute;cor material</p>\r\n</li>\r\n<li data-start=\"910\" data-end=\"964\">\r\n<p data-start=\"912\" data-end=\"964\">Customized stage themes (simple से लेकर luxury तक)</p>\r\n</li>\r\n<li data-start=\"965\" data-end=\"1020\">\r\n<p data-start=\"967\" data-end=\"1020\">Timely service aur client satisfaction की guarantee</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1022\" data-end=\"1191\">💍 Wedding stage ही आपकी शादी का <em data-start=\"1055\" data-end=\"1077\">center of attraction</em> होता है &ndash; और हमारी सजावट इसको royal aur stylish बना देती है, ताकि हर guest impressed हो और हर photo perfect आए।</p>\r\n<p data-start=\"1193\" data-end=\"1264\">👉 अभी बुक करें और अपनी शादी के stage को दें एक grand aur royal look!</p>'),
